package com.yeyamo_mobile.api.admin_service.event;
import static org.mockito.Mockito.*;import java.util.*;import org.junit.jupiter.api.Test;import com.fasterxml.jackson.databind.ObjectMapper;import com.yeyamo_mobile.api.admin_service.service.ValidationService;
class PartnerSubmittedConsumerTests{@Test void createsValidationOnceFromPartnerContract()throws Exception{ValidationService service=mock(ValidationService.class);AdminProcessedEventRepository processed=mock(AdminProcessedEventRepository.class);when(processed.existsById(any())).thenReturn(false);String event="{\"eventId\":\"33333333-3333-3333-3333-333333333333\",\"eventType\":\"partner.submitted\",\"payload\":{\"partnerId\":\"44444444-4444-4444-4444-444444444444\",\"kycDocumentKeys\":[\"p/doc.pdf\"],\"kycDocumentTypes\":[\"OWNER_IDENTITY\"]}}";new PartnerSubmittedConsumer(new ObjectMapper(),service,processed).consume(event);verify(service).createPartnerValidationFromEvent(UUID.fromString("44444444-4444-4444-4444-444444444444"),List.of("p/doc.pdf"),List.of("OWNER_IDENTITY"));verify(processed).save(any(AdminProcessedEvent.class));}}
